css:
.vd { position: relative; min-height: 380px; display: flex; align-items: center; overflow: hidden; }

.vd-foto { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

/* Piso de contraste na coluna do texto — a foto muda, a legibilidade não. */
.vd-veu-h {
  position: absolute; inset: 0;
  background: linear-gradient(to right, rgba(0,0,0,0.92), rgba(0,0,0,0.75) 45%, rgba(0,0,0,0.25));
}

/* Dissolve no fundo da PÁGINA: termina em var(--bg), não em preto fixo, senão
   a emenda aparece assim que a seção seguinte mudar de cor. */
.vd-veu-v {
  position: absolute; inset: 0;
  background: linear-gradient(to top, var(--bg), transparent 60%, rgba(0,0,0,0.7));
}

.vd-conteudo { position: relative; max-width: 560px; padding: 56px 40px; }
.vd-titulo {
  margin: 0 0 14px;
  font-family: 'Sora', sans-serif; font-weight: 700; font-size: clamp(24px, 3.4vw, 36px);
  letter-spacing: -0.02em; line-height: 1.15;
}
.vd-desc { margin: 0; color: var(--text-muted); line-height: 1.65; }

@media (max-width: 640px) { .vd-conteudo { padding: 40px 24px; } }
